// Keeps src-tauri/permissions/autogenerated/ in step with the commands
// registered in main.rs - run automatically before every `npm run tauri ...`
// (see "pretauri" in package.json), or by hand: `npm run permissions`.
//
// Why this exists: Tauri's build validates that every `allow-<command>`
// entry in capabilities/*.json has a matching permission definition, and in
// this project those definitions are .toml files that were maintained by
// hand. Add a command to generate_handler![...] and forget its .toml and the
// build fails with "Permission allow-xyz not found". This script creates any
// missing .toml files, byte-for-byte in the format the existing ones use.
//
// What it deliberately does NOT do: edit capabilities/*.json. Granting the
// chrome UI access to a command is a security decision, so if a command isn't
// allowed in any capability the script only warns - it never grants access.
//
// No dependencies; plain Node. Set KITE_ROOT to run against another checkout.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root =
  process.env.KITE_ROOT ||
  path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const mainRs = path.join(root, "src-tauri", "src", "main.rs");
const permDir = path.join(root, "src-tauri", "permissions", "autogenerated");
const capDir = path.join(root, "src-tauri", "capabilities");

function fail(msg) {
  console.error(`[permissions] ${msg}`);
  process.exit(1);
}

if (!fs.existsSync(mainRs)) fail(`can't find ${mainRs}`);

// ---- 1. commands registered with generate_handler![ ... ]
const source = fs.readFileSync(mainRs, "utf8");
const match = source.match(/generate_handler!\s*\[([\s\S]*?)\]/);
if (!match) fail("couldn't find generate_handler![...] in main.rs");
const body = match[1]
  .replace(/\/\*[\s\S]*?\*\//g, "") // block comments
  .replace(/\/\/[^\n]*/g, ""); // line comments
const commands = [
  ...new Set(
    body
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean)
      .map((t) => t.split("::").pop())
  ),
];
for (const c of commands) {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(c)) {
    fail(`unexpected entry in generate_handler!: "${c}" (script needs updating?)`);
  }
}
if (commands.length === 0) fail("generate_handler! lists no commands");

// ---- 2. which commands already have a permission definition?
fs.mkdirSync(permDir, { recursive: true });
const defined = new Set();
for (const f of fs.readdirSync(permDir)) {
  if (!f.endsWith(".toml")) continue;
  const text = fs.readFileSync(path.join(permDir, f), "utf8");
  for (const m of text.matchAll(/commands\.allow\s*=\s*\[\s*"([^"]+)"\s*\]/g)) {
    defined.add(m[1]);
  }
}

// ---- 3. create the missing ones
const created = [];
for (const cmd of commands) {
  if (defined.has(cmd)) continue;
  const id = cmd.replace(/_/g, "-");
  const toml =
    `# Automatically generated - DO NOT EDIT!\n\n` +
    `[[permission]]\n` +
    `identifier = "allow-${id}"\n` +
    `description = "Enables the ${cmd} command without any pre-configured scope."\n` +
    `commands.allow = ["${cmd}"]\n\n` +
    `[[permission]]\n` +
    `identifier = "deny-${id}"\n` +
    `description = "Denies the ${cmd} command without any pre-configured scope."\n` +
    `commands.deny = ["${cmd}"]\n`;
  fs.writeFileSync(path.join(permDir, `${cmd}.toml`), toml);
  created.push(cmd);
}

// ---- 4. warn about commands no capability grants (never auto-granted)
const granted = new Set();
if (fs.existsSync(capDir)) {
  for (const f of fs.readdirSync(capDir)) {
    if (!f.endsWith(".json")) continue;
    try {
      const cap = JSON.parse(fs.readFileSync(path.join(capDir, f), "utf8"));
      for (const p of cap.permissions || []) {
        if (typeof p === "string") granted.add(p);
      }
    } catch (e) {
      console.warn(`[permissions] couldn't read capabilities/${f}: ${e.message}`);
    }
  }
}
const ungranted = commands.filter((c) => !granted.has(`allow-${c.replace(/_/g, "-")}`));

if (created.length) {
  console.log(
    `[permissions] created ${created.length} missing permission file(s): ${created.join(", ")}`
  );
} else {
  console.log(`[permissions] ok - all ${commands.length} commands have permission files`);
}
if (ungranted.length) {
  console.warn(
    `[permissions] WARNING: ${ungranted.length} command(s) aren't allowed in any capability, ` +
      `so no webview can call them: ${ungranted.join(", ")}\n` +
      `              Add "allow-<name-with-dashes>" to src-tauri/capabilities/chrome.json (or content.json) if they should be callable.`
  );
}
